import { useEffect, useState, useCallback, useMemo } from 'react';
import { View, Text, ScrollView, RefreshControl, ActivityIndicator, Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Clipboard from 'expo-clipboard';
import CtaCard from '../components/duels/CtaCard';
import MentorCard from '../components/teachers/MentorCard';
import MentorFilters from '../components/teachers/MentorFilters';
import JoinClassPopup from '../components/teachers/JoinClassPopup';
import Popup from '../components/Popup';
import { ErrorRetry } from '../components/ErrorRetry';
import { getMentors, getReferral } from '../api';
import { COLORS, TAB_CLEARANCE } from '../theme';
import CatLoader from '../components/CatLoader';

function priceMatches(price, active) {
  if (active === 'any') return true;
  if (price == null) return false;
  if (active === '0-20') return price <= 20;
  if (active === '20-40') return price >= 20 && price <= 40;
  if (active === '40+') return price > 40;
  return true;
}

export default function TeachersScreen({ onBack }) {
  const [mentors, setMentors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  const [activeLang, setActiveLang] = useState('');
  const [activePrice, setActivePrice] = useState('any');

  const [showJoin, setShowJoin] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [copied, setCopied] = useState(false);        // code copié
  const [copiedLink, setCopiedLink] = useState(false); // lien copié (option secondaire)

  const load = useCallback(async () => {
    setError('');
    try {
      const d = await getMentors();
      setMentors(d.mentors || []);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const languages = useMemo(() => {
    const set = new Set();
    mentors.forEach((m) => (m.teaching_languages || []).forEach((l) => set.add(l)));
    return [...set].sort();
  }, [mentors]);

  const filtered = mentors.filter((m) =>
    (!activeLang || (m.teaching_languages || []).some((l) => l.toLowerCase() === activeLang.toLowerCase()))
    && priceMatches(m.session_price, activePrice)
  );

  function openInvite() {
    setCopied(false); setCopiedLink(false);
    setShowInvite(true);
    if (!inviteCode) getReferral().then((r) => { setInviteCode(r.code); setInviteLink(r.link); }).catch(() => {});
  }
  async function copyInviteCode() {
    if (!inviteCode) return;
    try { await Clipboard.setStringAsync(inviteCode); setCopied(true); setTimeout(() => setCopied(false), 2000); } catch { /* noop */ }
  }
  async function copyInvite() {
    if (!inviteLink) return;
    try { await Clipboard.setStringAsync(inviteLink); setCopiedLink(true); setTimeout(() => setCopiedLink(false), 2000); } catch { /* noop */ }
  }

  if (loading) {
    return <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: '#f8f9fa' }}><CatLoader size={110} /></View>;
  }
  if (error) {
    return <View style={{ flex: 1, backgroundColor: '#f8f9fa' }}><ErrorRetry error={error} onRetry={load} /></View>;
  }

  return (
    <View style={{ flex: 1, backgroundColor: '#f8f9fa' }}>
      <ScrollView
        contentContainerStyle={{ paddingTop: 16, paddingBottom: TAB_CLEARANCE }}
        refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => { setRefreshing(true); load(); }} tintColor={COLORS.jiayou} />}
      >
        <View style={{ width: '100%', maxWidth: 700, alignSelf: 'center', paddingHorizontal: 16 }}>
          {onBack ? (
            <Pressable onPress={onBack} hitSlop={10} style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginBottom: 12 }}>
              <Ionicons name="chevron-back" size={20} color={COLORS.jiayou} />
              <Text style={{ color: COLORS.jiayou, fontWeight: '600' }}>Back</Text>
            </Pressable>
          ) : null}
          {/* CTA : rejoindre une classe + inviter son prof */}
          <View style={{ flexDirection: 'row', gap: 14, marginBottom: 16 }}>
            <CtaCard colors={['#0d6efd', '#0a58ca']} icon="enter" title="Join a class" text="Enter a code" onPress={() => setShowJoin(true)} />
            <CtaCard colors={['#4b5158', '#2b2f36']} icon="person-add" title="Invite your teacher" text="Earn 150 coins" onPress={openInvite} />
          </View>

          {/* Filtres */}
          {mentors.length > 0 && (
            <MentorFilters
              languages={languages}
              activeLang={activeLang} onLang={setActiveLang}
              activePrice={activePrice} onPrice={setActivePrice}
            />
          )}

          {/* Liste des mentors */}
          {mentors.length === 0 ? (
            <View style={{ alignItems: 'center', paddingVertical: 40 }}>
              <Text style={{ fontSize: 40 }}>🧑‍🏫</Text>
              <Text style={{ color: COLORS.muted, marginTop: 8 }}>No teachers listed yet. Check back soon!</Text>
            </View>
          ) : filtered.length === 0 ? (
            <View style={{ alignItems: 'center', paddingVertical: 30 }}>
              <Ionicons name="search" size={34} color={COLORS.muted} />
              <Text style={{ color: COLORS.muted, marginTop: 8, fontSize: 13 }}>No teacher matches these filters.</Text>
            </View>
          ) : (
            filtered.map((m) => <MentorCard key={m.id} mentor={m} />)
          )}
        </View>
      </ScrollView>

      <JoinClassPopup visible={showJoin} onClose={() => setShowJoin(false)} onJoined={load} />

      {/* Invite your teacher (référence → 150 coins) */}
      <Popup visible={showInvite} onClose={() => setShowInvite(false)} maxWidth={380}>
        <Text style={{ fontSize: 17, fontWeight: '700', color: '#1a1a2e', marginBottom: 8 }}>Invite your teacher</Text>
        <Text style={{ fontSize: 14, color: COLORS.muted, lineHeight: 20, marginBottom: 16 }}>
          Share your code. Your teacher enters it when signing up — you earn 150 coins and they start with +50.
        </Text>
        {/* Code de parrainage mis en avant (le prof le saisit à l'inscription) */}
        <View style={{ backgroundColor: '#f8f9fa', borderWidth: 1, borderColor: '#e3e8f7', borderRadius: 12, paddingVertical: 16, paddingHorizontal: 14, marginBottom: 16, alignItems: 'center' }}>
          <Text style={{ fontSize: 26, fontWeight: '800', letterSpacing: 4, color: inviteCode ? '#1a1a2e' : '#adb5bd' }}>
            {inviteCode || '·······'}
          </Text>
        </View>
        <View style={{ flexDirection: 'row', gap: 12 }}>
          <Pressable onPress={() => setShowInvite(false)} style={{ flex: 1, backgroundColor: '#f1f3f5', borderRadius: 999, paddingVertical: 13, alignItems: 'center' }}>
            <Text style={{ color: COLORS.muted, fontWeight: '700' }}>Close</Text>
          </Pressable>
          <Pressable onPress={copyInviteCode} disabled={!inviteCode} style={{ flex: 1, backgroundColor: copied ? COLORS.success : COLORS.jiayou, borderRadius: 999, paddingVertical: 13, alignItems: 'center', flexDirection: 'row', justifyContent: 'center', gap: 6, opacity: inviteCode ? 1 : 0.6 }}>
            <Ionicons name={copied ? 'checkmark' : 'copy-outline'} size={16} color="#fff" />
            <Text style={{ color: '#fff', fontWeight: '700' }}>{copied ? 'Copied!' : 'Copy my code'}</Text>
          </Pressable>
        </View>
        <Pressable onPress={copyInvite} disabled={!inviteLink} style={{ paddingVertical: 12, alignItems: 'center', marginTop: 4 }}>
          <Text style={{ fontSize: 13, color: copiedLink ? COLORS.success : COLORS.jiayou, fontWeight: '600' }}>
            {copiedLink ? 'Copied!' : 'or copy an invite link instead'}
          </Text>
        </Pressable>
      </Popup>
    </View>
  );
}
